}

func WriteJSONResponseError(
	ctx context.Context,
	l *slog.Logger,
	w http.ResponseWriter,
	r *http.Request,
	err error,
) {
	l.ErrorContext(
		ctx,
		"writing json error",
		"method", r.Method,
		"path", r.URL.Path,
		slogutil.KeyError, err,
	)

	WriteJSONResponse(ctx, l, w, r, http.StatusUnprocessableEntity, &HTTPAPIErrorResp{
		Code: ErrorCodeTMP000,
		Msg:  err.Error(),
	})
}

