type HostsContainer struct {
	// logger is used for logging the operation of the hosts container.  It must
	// not be nil.
	logger *slog.Logger

	// done is the channel to signal closing the container.
	done chan struct{}

	// updates is the channel for receiving updated hosts.
	updates chan *hostsfile.DefaultStorage

	// current is the last set of hosts parsed.
	current atomic.Pointer[hostsfile.DefaultStorage]

	// fsys is the working file system to read hosts files from.  It must not be
	// nil.
	fsys fs.FS

	// watcher tracks the changes in specified files and directories.  It must
	// not be nil.
	watcher aghos.FSWatcher

	// patterns stores specified paths in the fs.Glob-compatible form.
	patterns []string
}

func NewHostsContainer(
	ctx context.Context,
	l *slog.Logger,
	fsys fs.FS,
	w aghos.FSWatcher,
	paths ...string,
) (hc *HostsContainer, err error) {
	defer func() { err = errors.Annotate(err, "%s: %w", hostsContainerPrefix) }()

	if len(paths) == 0 {
		return nil, ErrNoHostsPaths
	}

	var patterns []string
	patterns, err = pathsToPatterns(fsys, paths)
	if err != nil {
		return nil, err
	} else if len(patterns) == 0 {
		return nil, ErrNoHostsPaths
	}

	hc = &HostsContainer{
		logger:   l,
		done:     make(chan struct{}, 1),
		updates:  make(chan *hostsfile.DefaultStorage, 1),
		fsys:     fsys,
		watcher:  w,
		patterns: patterns,
	}

	l.DebugContext(ctx, "starting")

	// Load initially.
	if err = hc.refresh(ctx); err != nil {
		return nil, err
	}

	// Don't use absolute paths for watching, since those are required to be
	// relative to the operating system root, not the current directory.  See
	// TODO at NewHostsContainer.
	rootDir := aghos.RootDir()

	for _, p := range paths {
		p = filepath.Join(rootDir, p)

		err = w.Add(p)
		if err != nil {
			if !errors.Is(err, fs.ErrNotExist) {
				return nil, fmt.Errorf("adding path: %w", err)
			}

			l.DebugContext(ctx, "expected path does not exist", "path", p, slogutil.KeyError, err)
		}
	}

	go hc.handleEvents(ctx)

	return hc, nil
}

func (hc *HostsContainer) Close() (err error) {
	// TODO(s.chzhen):  Pass context.
	ctx := context.TODO()
	hc.logger.DebugContext(ctx, "closing")

	err = errors.Annotate(hc.watcher.Shutdown(ctx), "closing fs watcher: %w")

	// Go on and close the container either way.
	close(hc.done)

	return err
}

func (hc *HostsContainer) ByAddr(addr netip.Addr) (names []string) {
	return hc.current.Load().ByAddr(addr)
}

func (hc *HostsContainer) ByName(name string) (addrs []netip.Addr) {
	return hc.current.Load().ByName(name)
}

func pathsToPatterns(fsys fs.FS, paths []string) (patterns []string, err error) {
	for i, p := range paths {
		var fi fs.FileInfo
		fi, err = fs.Stat(fsys, p)
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) {
				continue
			}

			// Don't put a filename here since it's already added by [fs.Stat].
			return nil, fmt.Errorf("path at index %d: %w", i, err)
		}

		if fi.IsDir() {
			p = path.Join(p, "*")
		}

		patterns = append(patterns, p)
	}

	return patterns, nil
}

func (hc *HostsContainer) handleEvents(ctx context.Context) {
	defer slogutil.RecoverAndLog(ctx, hc.logger)

	defer close(hc.updates)

	eventsCh := hc.watcher.Events()
	ok := eventsCh != nil
	for ok {
		select {
		case _, ok = <-eventsCh:
			if !ok {
				hc.logger.DebugContext(ctx, "watcher closed the events channel")

				continue
			}

			if err := hc.refresh(ctx); err != nil {
				hc.logger.ErrorContext(ctx, "refreshing", slogutil.KeyError, err)
			}
		case _, ok = <-hc.done:
			// Go on.
		}
	}
}

func (hc *HostsContainer) refresh(ctx context.Context) (err error) {
	hc.logger.DebugContext(ctx, "refreshing")

	// The error is always nil here since no readers passed.
	strg, _ := hostsfile.NewDefaultStorage(ctx, &hostsfile.DefaultStorageConfig{
		Logger: hc.logger,
	})
	_, err = aghos.FileWalker(func(r io.Reader) (patterns []string, cont bool, err error) {
		// Don't wrap the error since it's already informative enough as is.
		return nil, true, hostsfile.Parse(ctx, strg, r, nil)
	}).Walk(hc.fsys, hc.patterns...)
	if err != nil {
		// Don't wrap the error since it's informative enough as is.
		return err
	}

	// TODO(e.burkov):  Serialize updates using [time.Time].
	if !hc.current.Load().Equal(strg) {
		hc.current.Store(strg)
		hc.sendUpd(ctx, strg)
	}

	return nil
}

type IgnoreEngine struct {
	// engine is the filtering engine that can match rules for ignoring
	// hostnames.
	engine *urlfilter.DNSEngine

	// ignored is the list of rules for ignoring hostnames.
	ignored []string

	// enabled determines whether ignoring is enabled.
	enabled bool
}

func NewIgnoreEngine(ignored []string, enabled bool) (e *IgnoreEngine, err error) {
	ruleLists := []filterlist.Interface{
		filterlist.NewString(&filterlist.StringConfig{
			RulesText:      strings.ToLower(strings.Join(ignored, "\n")),
			IgnoreCosmetic: true,
		}),
	}
	ruleStorage, err := filterlist.NewRuleStorage(ruleLists)
	if err != nil {
		return nil, err
	}

	return &IgnoreEngine{
		engine:  urlfilter.NewDNSEngine(ruleStorage),
		ignored: ignored,
		enabled: enabled,
	}, nil
}

func (e *IgnoreEngine) Has(host string) (ignore bool) {
	if e == nil || !e.enabled {
		return false
	}

	_, ignore = e.engine.Match(host)

	return ignore
}

func (e *IgnoreEngine) Values() (ignored []string) {
	return slices.Clone(e.ignored)
}

func (e *IgnoreEngine) IsEnabled() (enabled bool) {
	return e.enabled
}

func reuseAddrCtrl(_, _ string, c syscall.RawConn) (err error) {
	cerr := c.Control(func(fd uintptr) {
		// TODO(e.burkov):  Consider using SO_REUSEPORT.
		err = unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEADDR, 1)
		if err != nil {
			err = os.NewSyscallError("setsockopt", err)
		}
	})

	err = errors.Join(err, cerr)

	return errors.Annotate(err, "setting control options: %w")
}

func listenPacketReusable(_, network, address string) (c net.PacketConn, err error) {
	var lc net.ListenConfig
	lc.Control = reuseAddrCtrl

	return lc.ListenPacket(context.Background(), network, address)
}

func listenPacketReusable(ifaceName, network, address string) (c net.PacketConn, err error) {
	var port uint16
	_, port, err = netutil.SplitHostPort(address)
	if err != nil {
		return nil, err
	}

	// TODO(e.burkov):  Inspect nclient4.NewRawUDPConn and implement here.
	return nclient4.NewRawUDPConn(ifaceName, int(port))
}

func IfaceIPAddrs(iface NetIface, ipv IPVersion) (ips []net.IP, err error) {
	switch ipv {
	case IPVersion4, IPVersion6:
		// Go on.
	default:
		return nil, fmt.Errorf("invalid ip version %d", ipv)
	}

	addrs, err := iface.Addrs()
	if err != nil {
		return nil, err
	}

	for _, a := range addrs {
		if ip := ipFromAddr(a, ipv); ip != nil {
			ips = append(ips, ip)
		}
	}

	return ips, nil
}

func IfaceDNSIPAddrs(
	ctx context.Context,
	l *slog.Logger,
	iface NetIface,
	ipv IPVersion,
	maxAttempts int,
	backoff time.Duration,
) (addrs []net.IP, err error) {
	var n int
	for n = 1; n <= maxAttempts; n++ {
		addrs, err = IfaceIPAddrs(iface, ipv)
		if err != nil {
			return nil, fmt.Errorf("getting ip addrs: %w", err)
		}

		if len(addrs) > 0 {
			break
		}

		l.DebugContext(ctx, "no ip addresses", "attempt", n, "ipv", ipv)

		time.Sleep(backoff)
	}

	n--

	switch len(addrs) {
	case 0:
		// Don't return errors in case the users want to try and enable the DHCP
		// server later.
		t := time.Duration(n) * backoff
		l.ErrorContext(ctx, "no ip addresses for iface", "attempts", n, "duration", t, "ipv", ipv)

		return nil, nil
	case 1:
		// Some Android devices use 8.8.8.8 if there is not a secondary DNS
		// server.  Fix that by setting the secondary DNS address to the same
		// address.
		//
		// See https://github.com/AdguardTeam/AdGuardHome/issues/1708.
		l.DebugContext(ctx, "setting secondary dns ip to itself", "ipv", ipv)
		addrs = append(addrs, addrs[0])
	default:
		// Go on.
	}

	l.DebugContext(ctx, "got addresses", "addrs", addrs, "attempts", n, "ipv", ipv)

	return addrs, nil
}

